  --color-border:       #2e3350;
  --color-border-focus: #7c8cff;
  --color-text:         #e8eaf6;
  --color-text-muted:   #9ea3c0;
  --color-accent:       #7c8cff;
  --color-accent-hover: #a0adff;
  --color-error:        #ff6b6b;
  --color-error-bg:     rgba(255, 107, 107, 0.12);
  --color-success:      #4caf82;
  --color-success-bg:   rgba(76, 175, 130, 0.12);
  --color-radio-dot:    #7c8cff;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;

  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

html {
  font-family: var(--font-sans);
  font-size: 16px;
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
}

/* =====================
   Skip link
   ===================== */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 1rem;
  z-index: 100;
  padding: 0.5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
}
.skip-link:focus {
  top: 1rem;
}

/* =====================
   Page layout
   ===================== */
.page-header {
  padding: 2rem 1rem 1.5rem;
  text-align: center;
  border-bottom: 1px solid var(--color-border);
}

.page-header h1 {
  font-size: clamp(1.4rem, 4vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

main {
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: calc(100vh - 90px);
  padding: 3rem 1rem;
}

.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: clamp(1.5rem, 4vw, 2.5rem);
  width: 100%;
  max-width: 520px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.card-title {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: var(--color-text);
}

.card-subtitle {
  font-size: 0.9rem;
  color: var(--color-text-muted);
  margin-bottom: 2rem;
}

/* =====================
   Required legend
   ===================== */
.required-note {
  font-size: 0.8rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
}

.required-note span[aria-hidden="true"] {
  color: var(--color-error);
  font-weight: 700;
}

/* =====================
   Form field wrapper
   ===================== */
.form-field {
  margin-bottom: 1.75rem;
}

.form-field fieldset {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1.25rem 1.25rem 1.25rem;
  background: var(--color-surface-alt);
  transition: border-color 0.2s;
}

.form-field fieldset:focus-within {
  border-color: var(--color-border-focus);
}

.form-field legend {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text);
  padding: 0 0.5rem;
  line-height: 1.4;
}

.form-field legend .required-star {
  color: var(--color-error);
  margin-left: 0.2rem;
}

/* =====================
   Radio options
   ===================== */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 1rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  background: var(--color-surface);
  color: var(--color-text);
  font-size: 0.95rem;
  transition: background 0.15s, border-color 0.15s;
  user-select: none;
}

.radio-label:hover {
  background: rgba(124, 140, 255, 0.08);
  border-color: var(--color-accent);
}

/* Hide native radio, replace with custom */
.radio-label input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.125rem;
  height: 1.125rem;
  min-width: 1.125rem;
  border: 2px solid var(--color-border);
  border-radius: 50%;
  background: transparent;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
  position: relative;
  display: grid;
  place-items: center;
}

.radio-label input[type="radio"]::after {
  content: "";
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--color-radio-dot);
  opacity: 0;
  transform: scale(0);
  transition: opacity 0.15s, transform 0.15s;
}

.radio-label input[type="radio"]:checked {
  border-color: var(--color-accent);
}

.radio-label input[type="radio"]:checked::after {
  opacity: 1;
  transform: scale(1);
}

/* Highlight the selected row */
.radio-label:has(input[type="radio"]:checked) {
  border-color: var(--color-accent);
  background: rgba(124, 140, 255, 0.1);
}

/* Focus ring */
.radio-label input[type="radio"]:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* =====================
   Error state
   ===================== */
.field-error {
  display: none;
  margin-top: 0.6rem;
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  background: var(--color-error-bg);
  color: var(--color-error);
  font-size: 0.85rem;
  font-weight: 500;
}

.form-field[data-invalid="true"] fieldset {
  border-color: var(--color-error);
}

.form-field[data-invalid="true"] .field-error {
  display: block;
}

/* =====================
   Submit button
   ===================== */
.btn-submit {
  display: block;
  width: 100%;
  padding: 0.85rem 1.5rem;
  background: var(--color-accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  letter-spacing: 0.02em;
  transition: background 0.2s, transform 0.1s;
}

.btn-submit:hover {
  background: var(--color-accent-hover);
}

.btn-submit:active {
  transform: scale(0.98);
}

.btn-submit:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* =====================
   Status message (live region)
   ===================== */
.status-message {
  display: none;
  margin-top: 1.25rem;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
}

.status-message[data-type="success"] {
  display: block;
  background: var(--color-success-bg);
  color: var(--color-success);
  border: 1px solid rgba(76, 175, 130, 0.3);
}

.status-message[data-type="error"] {
  display: block;
  background: var(--color-error-bg);
  color: var(--color-error);
  border: 1px solid rgba(255, 107, 107, 0.3);
}

/* =====================
   Forced colors (Windows HC)
   ===================== */
@media (forced-colors: active) {
  .radio-label input[type="radio"] {
    forced-color-adjust: auto;
  }
  .btn-submit {
    forced-color-adjust: auto;
  }
}

/* =====================
   Reduced motion
   ===================== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
    animation: none !important;
  }
}

/* =====================
   Reflow / narrow viewports
   ===================== */
@media (max-width: 360px) {
  .card {
    padding: 1.25rem;
  }
  .radio-label {
    padding: 0.65rem 0.75rem;
  }
}
