  const form = document.getElementById('notification-form');
  const formField = document.getElementById('notification-field');
  const fieldError = document.getElementById('notification-error');
  const statusMsg = document.getElementById('form-status');

  function clearError() {
    formField.removeAttribute('data-invalid');
    fieldError.textContent = '';
  }

  function showError(msg) {
    formField.setAttribute('data-invalid', 'true');
    fieldError.textContent = msg;
  }

  function showStatus(msg, type) {
    statusMsg.textContent = msg;
    statusMsg.setAttribute('data-type', type);
  }

  function clearStatus() {
    statusMsg.removeAttribute('data-type');
    statusMsg.textContent = '';
  }

  // Clear error as soon as any radio is picked
  form.querySelectorAll('input[type="radio"]').forEach(radio => {
    radio.addEventListener('change', () => {
      clearError();
      clearStatus();
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    clearError();
    clearStatus();

    const selected = form.querySelector('input[name="notification"]:checked');

    if (!selected) {
      showError('Error: Please select a notification preference.');
      // Focus the first radio so keyboard/AT users land in the group
      form.querySelector('input[name="notification"]').focus();
      return;
    }

    const labels = {
      email: 'Email',
      sms: 'SMS',
      push: 'Push Notifications',
    };

    showStatus(
      `Preference saved: ${labels[selected.value] ?? selected.value}. Thank you!`,
      'success'
    );
  });
})();
