*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg:           #0f1117;
  --color-surface:      #1a1d27;
  --color-surface-alt:  #22263a;
  --color-border:       #2e3350;
  --color-border-focus: #7c8cff;
  --color-text:         #e8eaf6;
  --color-text-muted:   #9ea3c0;
  --color-accent:       #7c8cff;
